A hot product's cache entry expires under heavy traffic. What problem does this code address?

```ts
const inflight = new Map<string, Promise<Product>>()

function getProduct(id: string) {
  let p = inflight.get(id)
  if (!p) {
    p = loadFromDb(id).finally(() => inflight.delete(id))
    inflight.set(id, p)
  }
  return p
}
```
